#include <bits/stdc++.h>
using namespace std;

// Walk back from the target: the larger coordinate was produced by the last step, and % jumps over repeated steps.
const char *solve(long long sx, long long sy, long long tx, long long ty) {
    while (tx >= sx && ty >= sy) {
        if (tx == sx && ty == sy) return "Yes";
        if (tx > ty) {
            if (ty == sy) return (tx - sx) % ty == 0 ? "Yes" : "No";
            tx %= ty;
        } else {
            if (tx == sx) return (ty - sy) % tx == 0 ? "Yes" : "No";
            ty %= tx;
        }
    }
    return "No";
}

int main() {
    long long sx, sy, tx, ty;
    cin >> sx >> sy >> tx >> ty;
    cout << solve(sx, sy, tx, ty) << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static String solve(long sx, long sy, long tx, long ty) {
        while (tx >= sx && ty >= sy) {
            if (tx == sx && ty == sy) return "Yes";
            if (tx > ty) {
                if (ty == sy) return (tx - sx) % ty == 0 ? "Yes" : "No";
                tx %= ty;
            } else {
                if (tx == sx) return (ty - sy) % tx == 0 ? "Yes" : "No";
                ty %= tx;
            }
        }
        return "No";
    }

    public static void main(String[] args) throws IOException {
        long sx = nextLong(), sy = nextLong(), tx = nextLong(), ty = nextLong();
        System.out.print(solve(sx, sy, tx, ty) + "\n");
    }
}

