import (
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func solve(sx, sy, tx, ty int) string {
	for tx >= sx && ty >= sy {
		if tx == sx && ty == sy {
			return "Yes"
		}
		if tx > ty {
			if ty == sy {
				if (tx-sx)%ty == 0 {
					return "Yes"
				}
				return "No"
			}
			tx %= ty
		} else {
			if tx == sx {
				if (ty-sy)%tx == 0 {
					return "Yes"
				}
				return "No"
			}
			ty %= tx
		}
	}
	return "No"
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	sx, sy, tx, ty := nextInt(), nextInt(), nextInt(), nextInt()
	os.Stdout.WriteString(solve(sx, sy, tx, ty) + "\n")
}
